definition.script:
pipeline {
    agent any

    environment {
        IMAGE_TAG = "shieldops-scan-${env.COMMIT_SHA?.take(7) ?: 'latest'}"
        TRIVY_SEVERITY = "CRITICAL,HIGH"
        GITHUB_API = "https://api.github.com"
    }

    stages {

        stage('Checkout') {
            steps {
                script {
                    echo "=== Cloning repo: ${env.REPO_URL} ==="
                    sh """
                        rm -rf workspace-repo
                        git clone ${env.REPO_URL} workspace-repo
                        cd workspace-repo
                        if [ -n "${env.COMMIT_SHA}" ]; then
                            git checkout ${env.COMMIT_SHA} || true
                        fi
                    """
                }
            }
        }

        stage('Build Docker Image') {
            steps {
                script {
                    echo "=== Building Docker image: ${env.IMAGE_TAG} ==="
                    sh """
                        if [ -f workspace-repo/Dockerfile ]; then
                            docker build -t ${env.IMAGE_TAG} workspace-repo/
                        else
                            echo "No Dockerfile found — scanning repo filesystem instead"
                        fi
                    """
                }
            }
        }

        stage('Trivy Scan') {
            steps {
                script {
                    echo "=== Running Trivy vulnerability scan ==="
                    def exitCode = sh(
                        returnStatus: true,
                        script: """
                            if docker image inspect ${env.IMAGE_TAG} > /dev/null 2>&1; then
                                trivy image \
                                    --severity ${env.TRIVY_SEVERITY} \
                                    --exit-code 1 \
                                    --no-progress \
                                    --format table \
                                    ${env.IMAGE_TAG} | tee trivy-report.txt
                            else
                                trivy fs \
                                    --severity ${env.TRIVY_SEVERITY} \
                                    --exit-code 1 \
                                    --no-progress \
                                    --format table \
                                    workspace-repo/ | tee trivy-report.txt
                            fi
                        """
                    )
                    env.TRIVY_EXIT_CODE = exitCode.toString()
                    env.SCAN_STATUS = (exitCode == 0) ? "success" : "failure"
                    env.SCAN_DESCRIPTION = (exitCode == 0) \
                        ? "ShieldOps: No critical vulnerabilities found" \
                        : "ShieldOps: CRITICAL vulnerabilities detected!"
                    echo "Trivy exit code: ${exitCode}"
                }
            }
        }

        stage('Report to GitHub') {
            when {
                expression { env.GITHUB_TOKEN?.trim() && env.COMMIT_SHA?.trim() }
            }
            steps {
                script {
                    def repoPath = env.REPO_URL
                        .replaceAll('https://github.com/', '')
                        .replaceAll('.git', '')

                    echo "=== Posting status to GitHub: ${repoPath} ==="
                    sh """
                        curl -s -X POST \
                            -H "Authorization: token ${env.GITHUB_TOKEN}" \
                            -H "Accept: application/vnd.github.v3+json" \
                            ${env.GITHUB_API}/repos/${repoPath}/statuses/${env.COMMIT_SHA} \
                            -d '{
                                "state": "${env.SCAN_STATUS}",
                                "target_url": "${env.BUILD_URL}",
                                "description": "${env.SCAN_DESCRIPTION}",
                                "context": "ShieldOps / Trivy Scan"
                            }'
                    """
                }
            }
        }

        stage('Cleanup') {
            steps {
                sh """
                    docker rmi ${env.IMAGE_TAG} || true
                    rm -rf workspace-repo
                """
            }
        }
    }

    post {
        always {
            archiveArtifacts artifacts: 'trivy-report.txt', allowEmptyArchive: true
        }
        success {
            echo "✅ Scan passed — no critical vulnerabilities"
        }
        failure {
            echo "❌ Scan failed — critical vulnerabilities found or build error"
        }
    }
}
